messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Red vs Blue Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
    import * as THREE from './three.module.js';

    // --- Configuration ---
    const TRACK_LENGTH = 400;
    const FINISH_LINE_Z = -200;
    const START_LINE_Z = 50;
    const RACE_DURATION = 10; // Seconds for a full loop
    const OVERTAKE_POINT = 0.6; // Red car overtakes at 60% of race distance

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // Sky blue
    scene.fog = new THREE.Fog(0x87CEEB, 50, 300);

    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1);
    dirLight.position.set(50, 100, 50);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 2048;
    dirLight.shadow.mapSize.height = 2048;
    dirLight.shadow.camera.near = 0.5;
    dirLight.shadow.camera.far = 500;
    dirLight.shadow.camera.left = -100;
    dirLight.shadow.camera.right = 100;
    dirLight.shadow.camera.top = 100;
    dirLight.shadow.camera.bottom = -100;
    scene.add(dirLight);

    // --- Environment ---

    // Ground
    const groundGeo = new THREE.PlaneGeometry(2000, 2000);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x3a9d23 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.1;
    ground.receiveShadow = true;
    scene.add(ground);

    // Track
    const trackGeo = new THREE.PlaneGeometry(40, TRACK_LENGTH + 100);
    const trackMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.8 });
    const track = new THREE.Mesh(trackGeo, trackMat);
    track.rotation.x = -Math.PI / 2;
    track.position.z = (START_LINE_Z + FINISH_LINE_Z) / 2;
    track.receiveShadow = true;
    scene.add(track);

    // Finish Line
    const finishGeo = new THREE.PlaneGeometry(40, 4);
    // Create a checkerboard texture programmatically
    const canvas = document.createElement('canvas');
    canvas.width = 64;
    canvas.height = 64;
    const context = canvas.getContext('2d');
    context.fillStyle = '#ffffff';
    context.fillRect(0,0,64,64);
    context.fillStyle = '#000000';
    // Simple checker pattern
    for(let i=0; i<4; i++) {
        for(let j=0; j<4; j++) {
            if((i+j)%2 === 0) context.fillRect(i*16, j*16, 16, 16);
        }
    }
    const finishTex = new THREE.CanvasTexture(canvas);
    finishTex.wrapS = THREE.RepeatWrapping;
    finishTex.wrapT = THREE.RepeatWrapping;
    finishTex.repeat.set(10, 1);

    const finishMat = new THREE.MeshBasicMaterial({ map: finishTex });
    const finishLine = new THREE.Mesh(finishGeo, finishMat);
    finishLine.rotation.x = -Math.PI / 2;
    finishLine.position.set(0, 0.05, FINISH_LINE_Z);
    scene.add(finishLine);

    // Finish Line Arch
    const archGroup = new THREE.Group();
    const poleGeo = new THREE.CylinderGeometry(0.5, 0.5, 15);
    const poleMat = new THREE.MeshStandardMaterial({ color: 0xcccccc });
    const leftPole = new THREE.Mesh(poleGeo, poleMat);
    leftPole.position.set(-18, 7.5, FINISH_LINE_Z);
    const rightPole = new THREE.Mesh(poleGeo, poleMat);
    rightPole.position.set(18, 7.5, FINISH_LINE_Z);
    const topBar = new THREE.Mesh(new THREE.BoxGeometry(37, 2, 2), poleMat);
    topBar.position.set(0, 15, FINISH_LINE_Z);
    archGroup.add(leftPole, rightPole, topBar);
    scene.add(archGroup);


    // --- Car Factory ---
    function createCar(colorHex) {
        const carGroup = new THREE.Group();

        // Chassis
        const chassisGeo = new THREE.BoxGeometry(2.5, 1, 5);
        const chassisMat = new THREE.MeshStandardMaterial({ color: colorHex });
        const chassis = new THREE.Mesh(chassisGeo, chassisMat);
        chassis.position.y = 1;
        chassis.castShadow = true;
        chassis.receiveShadow = true;
        carGroup.add(chassis);

        // Cabin
        const cabinGeo = new THREE.BoxGeometry(2, 0.8, 2.5);
        const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 }); // Dark windows
        const cabin = new THREE.Mesh(cabinGeo, cabinMat);
        cabin.position.y = 1.9;
        cabin.position.z = -0.2;
        cabin.castShadow = true;
        carGroup.add(cabin);

        // Wheels
        const wheelGeo = new THREE.CylinderGeometry(0.6, 0.6, 0.4, 16);
        const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

        const positions = [
            { x: -1.3, y: 0.6, z: 1.5 },
            { x: 1.3, y: 0.6, z: 1.5 },
            { x: -1.3, y: 0.6, z: -1.5 },
            { x: 1.3, y: 0.6, z: -1.5 }
        ];

        positions.forEach(pos => {
            const wheel = new THREE.Mesh(wheelGeo, wheelMat);
            wheel.rotation.z = Math.PI / 2;
            wheel.position.set(pos.x, pos.y, pos.z);
            wheel.castShadow = true;
            carGroup.add(wheel);
        });

        return carGroup;
    }

    const redCar = createCar(0xff0000);
    const blueCar = createCar(0x0000ff);

    // Initial positions
    redCar.position.set(5, 0, START_LINE_Z);
    blueCar.position.set(-5, 0, START_LINE_Z);

    scene.add(redCar);
    scene.add(blueCar);

    // --- Animation Logic ---
    const clock = new THREE.Clock();
    let raceTime = 0;

    function updateCarPosition(car, progress, laneOffset) {
        // Calculate Z position based on progress (0 to 1)
        // Map 0..1 to START_LINE_Z .. FINISH_LINE_Z
        const dist = START_LINE_Z - FINISH_LINE_Z;
        const currentZ = START_LINE_Z - (dist * progress);

        car.position.z = currentZ;
        car.position.x = laneOffset;
    }

    function animate() {
        requestAnimationFrame(animate);

        const delta = clock.getDelta();
        raceTime += delta;

        // Loop race time
        if (raceTime > RACE_DURATION) raceTime = 0;

        // Normalized time (0 to 1)
        const t = raceTime / RACE_DURATION;

        // --- Blue Car Logic (Leads early, loses later) ---
        // Simple linear motion with slight easing
        let blueProgress = t; 
        // Make blue car slightly faster at start, but stops accelerating earlier
        if (t < 0.5) blueProgress = t * 1.1; // Sprint start
        else blueProgress = 0.55 + (t - 0.5) * 0.9; // Coasting

        // Clamp progress
        blueProgress = Math.min(Math.max(blueProgress, 0), 1);
        updateCarPosition(blueCar, blueProgress, -5);


        // --- Red Car Logic (Accelerates, overtakes) ---
        let redProgress = 0;

        // Phase 1: Slow start
        if (t < 0.3) {
            redProgress = t * 0.8; // Slower than blue
        } 
        // Phase 2: Massive acceleration
        else if (t < 0.8) {
            // Start from where we were at 0.3 (approx 0.24)
            // End at roughly 0.95 (winning)
            const phaseDuration = 0.5;
            const phaseT = (t - 0.3) / phaseDuration;
            // Ease in-out curve for acceleration
            const accel = phaseT * phaseT * (3 - 2 * phaseT); 

            redProgress = 0.24 + (0.71 * accel); 
        } 
        // Phase 3: Crossing finish
        else {
            redProgress = 0.95 + (t - 0.8) * 2.5;
        }

        redProgress = Math.min(Math.max(redProgress, 0), 1);
        updateCarPosition(redCar, redProgress, 5);


        // --- Camera Logic ---
        // Find the leader to follow
        let leader = redCar.position.z < blueCar.position.z ? redCar : blueCar;

        // Smooth camera follow
        const camTargetZ = leader.position.z - 25; // Behind the leader
        const camTargetY = 15; // Height
        const camTargetX = 0; // Centered between lanes

        camera.position.z += (camTargetZ - camera.position.z) * 0.1;
        camera.position.y += (camTargetY - camera.position.y) * 0.1;
        camera.position.x += (camTargetX - camera.position.x) * 0.1;

        camera.lookAt(0, 0, leader.position.z - 40); // Look ahead of leader

        renderer.render(scene, camera);
    }

    // Handle Resize
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // Start
    animate();

</script>
</body>
</html>
```
